update public.contextos set contenido='<p>Un paracaidista se lanza de un avión y registra su rapidez de caída en función del tiempo en la siguiente gráfica.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q98-grafica.webp" loading="lazy" alt="Gráfica original de rapidez frente al tiempo: la rapidez aumenta durante los primeros segundos y alcanza una meseta de 40 m/s."></figure>' where id='aacedfe6-d274-45b5-82df-c4d2bb8e262d' and contenido='<p>Un paracaidista se lanza de un avión y registra su rapidez de caída en función del tiempo en la siguiente gráfica.</p><figure class="ctx-fig"><svg viewBox="0 0 480 290" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Curva de rapidez contra tiempo. Sube muy rápido desde cero durante los primeros segundos y a partir de los 5 segundos se aplana en 40 metros por segundo, donde se mantiene hasta el final de la gráfica." font-family="var(--font-body), system-ui, sans-serif"><path d="M56 244H462M56 215.5H462M56 187H462M56 158.5H462M56 130H462M56 101.5H462M56 73H462M56 44.5H462M56 16H462" stroke="var(--color-line)" fill="none" stroke-dasharray="3 3"/><path d="M56 244H462" stroke="var(--color-line)" fill="none"/><g font-size="12" fill="var(--color-ink-faint)" text-anchor="end"><text x="49" y="248">0</text><text x="49" y="219.5">5</text><text x="49" y="191">10</text><text x="49" y="162.5">15</text><text x="49" y="134">20</text><text x="49" y="105.5">25</text><text x="49" y="77">30</text><text x="49" y="48.5">35</text><text x="49" y="20">40</text></g><g font-size="12" fill="var(--color-ink-soft)" text-anchor="middle"><text transform="translate(13,130) rotate(-90)">Rapidez (m/s)</text><text x="259" y="285">Tiempo (s)</text></g><g font-size="12" fill="var(--color-ink-soft)" text-anchor="middle"><text x="56" y="261">1</text><text x="101.1" y="261">3</text><text x="146.2" y="261">5</text><text x="191.3" y="261">7</text><text x="236.4" y="261">9</text><text x="281.6" y="261">11</text><text x="326.7" y="261">13</text><text x="371.8" y="261">15</text><text x="416.9" y="261">17</text><text x="462" y="261">19</text></g><polyline fill="none" stroke="var(--color-accent)" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" points="56,244 66.4,162.9 76.8,110.7 87.2,77 97.6,55.3 108.1,41.3 118.5,32.3 128.9,26.5 139.3,22.8 149.7,20.4 160.1,18.8 170.5,17.8 180.9,17.2 191.3,16.8 201.7,16.5 212.2,16.3 222.6,16.2 233,16.1 243.4,16.1 253.8,16.1 264.2,16 274.6,16 285,16 295.4,16 305.8,16 316.3,16 326.7,16 337.1,16 347.5,16 357.9,16 368.3,16 378.7,16 389.1,16 399.5,16 409.9,16 420.4,16 430.8,16 441.2,16 451.6,16 462,16"/></svg></figure>';
