if n <> 1 then raise exception 'Conflicto de revisión: F1 Q98 contexto'; end if;
update public.contextos set contenido='<p>En un experimento se tomaron medidas de la variación del volumen (ΔV) de un cubo de un material elástico (respecto a un volumen de referencia), de su temperatura (T) y de la presión (P) a la que se sometía. Los datos del experimento se muestran en la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><tr><th>P (atm)</th><th colspan="4"></th></tr><tr><td rowspan="2">1,0</td><td>T (°C)</td><td>32</td><td>35</td><td>40</td></tr><tr><td>ΔV (cm<sup>3</sup>)</td><td>1,1</td><td>1,6</td><td>1,9</td></tr><tr><td rowspan="2">1,1</td><td>T (°C)</td><td>31</td><td>36</td><td>39</td></tr><tr><td>ΔV (cm<sup>3</sup>)</td><td>0,9</td><td>1,2</td><td>1,4</td></tr><tr><td rowspan="2">1,3</td><td>T (°C)</td><td>29</td><td>33</td><td>38</td></tr><tr><td>ΔV (cm<sup>3</sup>)</td><td>0,7</td><td>0,8</td><td>1,0</td></tr></table></div>' where id='88c137f8-ea2d-4528-99ab-2ac4c7542548' and contenido='<p>En un experimento se tomaron medidas de la variación del volumen (ΔV) de un cubo de un material elástico (respecto a un volumen de referencia), de su temperatura (T) y de la presión (P) a la que se sometía. Los datos del experimento se muestran en la tabla.</p><table class="ctx-table"><tr><th>P (atm)</th><th colspan="4"></th></tr><tr><td rowspan="2">1,0</td><td>T (°C)</td><td>32</td><td>35</td><td>40</td></tr><tr><td>ΔV (cm<sup>3</sup>)</td><td>1,1</td><td>1,6</td><td>1,9</td></tr><tr><td rowspan="2">1,1</td><td>T (°C)</td><td>31</td><td>36</td><td>39</td></tr><tr><td>ΔV (cm<sup>3</sup>)</td><td>0,9</td><td>1,2</td><td>1,4</td></tr><tr><td rowspan="2">1,3</td><td>T (°C)</td><td>29</td><td>33</td><td>38</td></tr><tr><td>ΔV (cm<sup>3</sup>)</td><td>0,7</td><td>0,8</td><td>1,0</td></tr></table>';
