update public.contextos set contenido='<p>Se lanzan tres pelotas, L, M y N, desde la azotea de un edificio de 30 m de altura. La siguiente gráfica muestra la altura de las pelotas como función del tiempo.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q105-grafica.webp" loading="lazy" alt="Gráfica original de altura frente al tiempo. L es la curva punteada, M la discontinua y N la continua; las tres llegan al eje de altura cero."></figure>' where id='ca09125f-921d-4f0c-81a7-516d7b9d89b6' and contenido='<p>Se lanzan tres pelotas, L, M y N, desde la azotea de un edificio de 30 m de altura. La siguiente gráfica muestra la altura de las pelotas como función del tiempo.</p><figure class="ctx-fig"><svg viewBox="0 0 480 300" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Tres curvas que parten de 30 metros de altura en el instante cero. La punteada, L, baja y toca el suelo antes de los 2 segundos. La de rayas, M, baja algo más despacio y toca el suelo cerca de los 2,5 segundos. La continua, N, primero sube hasta unos 34 metros y después baja, tocando el suelo cerca de los 3,5 segundos." font-family="var(--font-body), system-ui, sans-serif"><path d="M56 254H462M56 224.3H462M56 194.5H462M56 164.8H462M56 135H462M56 105.3H462M56 75.5H462M56 45.8H462M56 16H462" stroke="var(--color-line)" fill="none" stroke-dasharray="3 3"/><path d="M56 254H462" stroke="var(--color-line)" fill="none"/><g font-size="12" fill="var(--color-ink-faint)" text-anchor="end"><text x="49" y="258">0</text><text x="49" y="228.3">5</text><text x="49" y="198.5">10</text><text x="49" y="168.8">15</text><text x="49" y="139">20</text><text x="49" y="109.3">25</text><text x="49" y="79.5">30</text><text x="49" y="49.8">35</text><text x="49" y="20">40</text></g><g font-size="12" fill="var(--color-ink-soft)" text-anchor="middle"><text transform="translate(13,135) rotate(-90)">Altura (m)</text><text x="259" y="295">Tiempo (s)</text></g><g font-size="12" fill="var(--color-ink-soft)" text-anchor="middle"><text x="56" y="271">0</text><text x="114" y="271">0,5</text><text x="172" y="271">1</text><text x="230" y="271">1,5</text><text x="288" y="271">2</text><text x="346" y="271">2,5</text><text x="404" y="271">3</text><text x="462" y="271">3,5</text></g><polyline fill="none" stroke="var(--color-accent)" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="2 4" points="56,75.5 62.8,78.8 69.5,82.3 76.3,85.9 83.1,89.8 89.8,93.9 96.6,98.2 103.4,102.7 110.1,107.4 116.9,112.3 123.7,117.4 130.4,122.7 137.2,128.2 144,133.9 150.7,139.8 157.5,145.9 164.3,152.2 171,158.7 177.8,165.5 184.6,172.4 191.3,179.5 198.1,186.8 204.9,194.4 211.6,202.1 218.4,210 225.2,218.2 231.9,226.5 238.7,235 245.5,243.8 252.2,252.7"/><text x="139.5" y="176.6" font-size="13" font-weight="700" fill="var(--color-ink)" text-anchor="middle">L</text><polyline fill="none" stroke="var(--color-accent)" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="9 5" points="56,75.5 65.7,75.7 75.3,76.3 85,77.4 94.7,78.8 104.3,80.7 114,82.9 123.7,85.6 133.3,88.7 143,92.2 152.7,96.2 162.3,100.5 172,105.3 181.7,110.4 191.3,116 201,122 210.7,128.4 220.3,135.2 230,142.4 239.7,150.1 249.3,158.1 259,166.6 268.7,175.5 278.3,184.8 288,194.5 297.7,204.6 307.3,215.2 317,226.1 326.7,237.5 336.3,249.2"/><text x="212.6" y="123.1" font-size="13" font-weight="700" fill="var(--color-ink)" text-anchor="middle">M</text><polyline fill="none" stroke="var(--color-accent)" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" points="56,75.5 69.5,69.7 83.1,64.7 96.6,60.5 110.1,57.2 123.7,54.6 137.2,52.9 150.7,51.9 164.3,51.8 177.8,52.5 191.3,54 204.9,56.3 218.4,59.4 231.9,63.3 245.5,68.1 259,73.6 272.5,80 286.1,87.1 299.6,95.1 313.1,103.9 326.7,113.5 340.2,123.9 353.7,135.1 367.3,147.1 380.8,160 394.3,173.6 407.9,188.1 421.4,203.3 434.9,219.4 448.5,236.3 462,254"/><text x="282.2" y="57.7" font-size="13" font-weight="700" fill="var(--color-ink)" text-anchor="middle">N</text></svg></figure>';
