update public.contextos set contenido='<p>Sebastián realiza un experimento para organizar diferentes materiales según sus características, escogiendo madera, acero y agua, en donde dichos materiales tienen la misma masa. Los resultados de su experimento se muestran en la siguiente tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Material</th><th>Densidad (kg/m<sup>3</sup>)</th><th>Calor específico (kCal/kg °C)</th><th>Tiempo en llegar a 35 °C (s)</th></tr><tr><td>Madera</td><td>400</td><td>0,12</td><td>39</td></tr><tr><td>Acero</td><td>7.850</td><td>0,57</td><td>9</td></tr><tr><td>Agua</td><td>1.000</td><td>1,07</td><td>70</td></tr></table></div>' where id='4d2da40e-1d04-455a-81af-7af5dc5fdd26' and contenido='<p>Sebastián realiza un experimento para organizar diferentes materiales según sus características, escogiendo madera, acero y agua, en donde dichos materiales tienen la misma masa. Los resultados de su experimento se muestran en la siguiente tabla.</p><table class="ctx-table"><tr><th>Material</th><th>Densidad (kg/m<sup>3</sup>)</th><th>Calor específico (kCal/kg °C)</th><th>Tiempo en llegar a 35 °C (s)</th></tr><tr><td>Madera</td><td>400</td><td>0,12</td><td>39</td></tr><tr><td>Acero</td><td>7.850</td><td>0,57</td><td>9</td></tr><tr><td>Agua</td><td>1.000</td><td>1,07</td><td>70</td></tr></table>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F2 Q103 contexto'; end if;
update public.contextos set contenido='<p>Una estudiante mide la presión y el volumen de aire cuando comprime el émbolo que hay sobre un tubo cerrado en uno de sus extremos, como se observa en la figura. Los datos obtenidos se muestran en la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Presión ejercida sobre el émbolo (atm)</th><th>Volumen de aire dentro del tubo (cm<sup>3</sup>)</th></tr><tr><td>0,10</td><td>10</td></tr><tr><td>0,20</td><td>5</td></tr><tr><td>0,30</td><td>3,3</td></tr><tr><td>0,40</td><td>2,5</td></tr></table></div><figure class="ctx-fig"><img src="img/figuras/fis/f2-q104-tubo.webp" loading="lazy" alt="Dos tubos cerrados por abajo con un émbolo encima. En el primero el émbolo está arriba y la columna de aire es larga; en el segundo, una flecha indica que el émbolo bajó y la columna de aire quedó corta."></figure>' where id='d879c9ab-dac2-4645-b655-2546a57d6b3f' and contenido='<p>Una estudiante mide la presión y el volumen de aire cuando comprime el émbolo que hay sobre un tubo cerrado en uno de sus extremos, como se observa en la figura. Los datos obtenidos se muestran en la tabla.</p><table class="ctx-table"><tr><th>Presión ejercida sobre el émbolo (atm)</th><th>Volumen de aire dentro del tubo (cm<sup>3</sup>)</th></tr><tr><td>0,10</td><td>10</td></tr><tr><td>0,20</td><td>5</td></tr><tr><td>0,30</td><td>3,3</td></tr><tr><td>0,40</td><td>2,5</td></tr></table><figure class="ctx-fig"><img src="img/figuras/fis/f2-q104-tubo.webp" loading="lazy" alt="Dos tubos cerrados por abajo con un émbolo encima. En el primero el émbolo está arriba y la columna de aire es larga; en el segundo, una flecha indica que el émbolo bajó y la columna de aire quedó corta."></figure>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F2 Q104 contexto'; end if;
update public.preguntas set opciones=array['Que aumente el doble, ya que en la ecuación se muestra la gravedad, y el peso depende de la aceleración de la gravedad y de la masa.','Que se mantenga igual, ya que en la ecuación se muestra la gravedad, y el peso depende de la aceleración de la gravedad y la masa.','Que disminuya 10 grados, pues como se observa en la ecuación, al aumentar la velocidad el ángulo de rotación del sistema disminuye.','Que aumente la mitad, puesto que al elevar la velocidad al cuadrado el ángulo de rotación aumenta en esa misma proporción, debido a la masa.'],hash_norm='0ce3d83afb588b51e6a9fb1923bd6d9b',tip='Antes de razonar, haz la lista de lo que aparece en la ecuación. Lo que no aparece, no influye.' where id='d0cbe4eb-2088-4667-8a00-688d1b598068' and opciones=array['Que aumente el doble, ya que en la ecuación se muestra la gravedad, y el peso depende de la aceleración de la gravedad y de la masa.','Que se mantenga igual, ya que en la ecuación no aparece la masa: el ángulo solo depende de la velocidad y de la distancia.','Que disminuya 10 grados, pues como se observa en la ecuación, al aumentar la velocidad el ángulo de rotación del sistema disminuye.','Que aumente la mitad, puesto que al elevar la velocidad al cuadrado el ángulo de rotación aumenta en esa misma proporción, debido a la masa.'] and hash_norm='0ce3d83afb588b51e6a9fb1923bd6d9b' and tip='Antes de razonar, haz la lista de lo que aparece en la ecuación. Lo que no aparece, no influye.';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F2 Q105 pregunta'; end if;
update public.preguntas_clave set explicacion='En la ecuación aparecen tres cosas: la velocidad, la distancia y la gravedad. La masa no está por ningún lado, así que subirse alguien que pesa el doble no cambia el resultado. Es lo mismo que pasa con los cuerpos que caen: la masa se cancela. Si la atracción gira a la misma velocidad y a la misma distancia, el brazo se inclina el mismo ángulo con Juan que con su compañera. La conclusión de que el ángulo no cambia es compatible con la ecuación, donde la masa no aparece. Sin embargo, la justificación impresa de esa opción es imprecisa. Además, el dibujo mide θ desde la vertical, aunque el texto menciona el brazo horizontal. Se conserva el original para revisión docente.' where pregunta_id='d0cbe4eb-2088-4667-8a00-688d1b598068' and correcta=1 and explicacion='En la ecuación aparecen tres cosas: la velocidad, la distancia y la gravedad. La masa no está por ningún lado, así que subirse alguien que pesa el doble no cambia el resultado. Es lo mismo que pasa con los cuerpos que caen: la masa se cancela. Si la atracción gira a la misma velocidad y a la misma distancia, el brazo se inclina el mismo ángulo con Juan que con su compañera.';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F2 Q105 explicación'; end if;
update public.contextos set contenido='<p>Un correntómetro es un instrumento usado para medir la velocidad de una corriente de agua, el cual está equipado de una hélice que gira por la corriente líquida que choca con sus aspas, un contrapeso para evitar que se incline cuando se sumerge, una barra graduada para medir la profundidad y un tornillo de bloqueo para ajustar la hélice a la distancia requerida, como se muestra a continuación.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q108-helice.webp" loading="lazy" alt="Correntómetro: una hélice montada en un eje horizontal, sujeta a una barra vertical graduada de 01 a 05 mediante un tornillo de bloqueo, y un contrapeso en el extremo inferior de la barra."></figure><p>Actualmente, los correntómetros usan un contador de revoluciones, en donde los imanes establecen un contacto eléctrico con el sensor que envía la señal al contador, como se muestra en la siguiente figura.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q108-sensor.webp" loading="lazy" alt="Detalle del mecanismo: una pieza curva con imanes incrustados pasa frente a un sensor, que queda fijo junto a ella."></figure><p>Luego de una prueba en un río, el correntómetro marca los siguientes resultados:</p><div class="ctx-datos" role="region" aria-label="Resultados del correntómetro" tabindex="0"><table class="ctx-table ctx-table-nativa"><caption>Resultados del correntómetro</caption><thead><tr><th scope="col">Profundidad (m)</th><th scope="col">Velocidad (m/s)</th></tr></thead><tbody><tr><th scope="row">1,15</th><td>0,16</td></tr><tr><th scope="row">3,63</th><td>0,54</td></tr><tr><th scope="row">5,20</th><td>0,90</td></tr><tr><th scope="row">5,66</th><td>1,09</td></tr></tbody></table></div>' where id='89ad162b-a9a4-48fe-af5c-728ac11dafb6' and contenido='<p>Un correntómetro es un instrumento usado para medir la velocidad de una corriente de agua, el cual está equipado de una hélice que gira por la corriente líquida que choca con sus aspas, un contrapeso para evitar que se incline cuando se sumerge, una barra graduada para medir la profundidad y un tornillo de bloqueo para ajustar la hélice a la distancia requerida, como se muestra a continuación.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q108-helice.webp" loading="lazy" alt="Correntómetro: una hélice montada en un eje horizontal, sujeta a una barra vertical graduada de 01 a 05 mediante un tornillo de bloqueo, y un contrapeso en el extremo inferior de la barra."></figure><p>Actualmente, los correntómetros usan un contador de revoluciones, en donde los imanes establecen un contacto eléctrico con el sensor que envía la señal al contador, como se muestra en la siguiente figura.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q108-sensor.webp" loading="lazy" alt="Detalle del mecanismo: una pieza curva con imanes incrustados pasa frente a un sensor, que queda fijo junto a ella."></figure>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F2 Q108 contexto'; end if;
update public.preguntas set opciones=array['En la barra graduada, porque la velocidad del agua depende de la profundidad.','En el tornillo de bloqueo, porque el imán estaría fijo en todo momento.','En el contrapeso, porque es el elemento que da estabilidad al correntómetro.','En la hélice, porque esta gira gracias a la velocidad del agua.'],hash_norm='67f7ee7cfd8d4e7ce285e90801226a45',tip='Pregúntate qué pieza se mueve cuando el agua corre. El imán tiene que ir en esa, no en las que sostienen el aparato.' where id='4bfa48e3-2fea-4787-bbb7-af78058f3eee' and opciones=array['En la barra graduada, porque la velocidad del agua depende de la profundidad.','En el tornillo de bloqueo, porque el imán estaría fijo en todo momento.','En el contrapeso, porque es el elemento que da estabilidad al correntómetro.','En la hélice, porque esta gira gracias a la velocidad del agua.'] and hash_norm='2691133dcb0effb2378d382fe063384a' and tip='Pregúntate qué pieza se mueve cuando el agua corre. El imán tiene que ir en esa, no en las que sostienen el aparato.';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F2 Q108 pregunta'; end if;
update public.contextos set contenido='<p>Se tienen 3 resistencias idénticas conectadas a una batería formando los circuitos mostrados en las figuras.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q109-circuitos.webp" loading="lazy" alt="Cuatro circuitos con resistencias idénticas R: 1, tres en serie; 2, una en serie con dos en paralelo; 3, tres en paralelo; 4, una rama con R en paralelo con otra rama de dos resistencias en serie."></figure>' where id='d9c1f749-cf29-4908-a290-618c123993ca' and contenido='<p>Se tienen 3 resistencias idénticas conectadas a una batería formando los circuitos mostrados en las figuras.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q109-circuitos.webp" loading="lazy" alt="Cuatro circuitos con la misma batería y tres resistencias iguales. En el primero las tres van una detrás de otra. En el segundo, dos van en paralelo y la tercera en serie con ellas. En el tercero, las tres van en paralelo, cada una en su propia rama. En el cuarto, dos van en paralelo y la tercera en serie."></figure>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F2 Q109 contexto'; end if;
update public.contextos set contenido='<p>Dos partículas de polvo cargadas están separadas a una misma distancia de una pantalla larga que tiene una carga eléctrica positiva. La pantalla ejerce una fuerza sobre las partículas de igual magnitud y en direcciones opuestas, generando que las partículas experimenten aceleraciones como se muestra en la siguiente figura.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q115-particulas.webp" loading="lazy" alt="Una pantalla vertical cargada positivamente. A un lado, a 1 cm, la partícula 1 con su vector aceleración apuntando hacia la pantalla; al otro lado, también a 1 cm, la partícula 2 con su vector aceleración apuntando hacia la pantalla en sentido contrario. El vector de la partícula 1 es el doble de largo que el de la partícula 2."></figure><p>Una estudiante nota que, de acuerdo a la figura, la magnitud de aceleración en la partícula 1 es el doble que la de la partícula 2.</p>' where id='8d5ee686-8bb6-4b66-ae55-5d110ebde491' and contenido='<p>Dos partículas de polvo cargadas están separadas a una misma distancia de una pantalla larga que tiene una carga eléctrica positiva. La pantalla ejerce una fuerza sobre las partículas de igual magnitud y en direcciones opuestas, generando que las partículas experimenten aceleraciones como se muestra en la siguiente figura.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q115-particulas.webp" loading="lazy" alt="Una pantalla vertical cargada positivamente. A un lado, a 1 cm, la partícula 1 con su vector aceleración apuntando hacia afuera; al otro lado, también a 1 cm, la partícula 2 con su vector aceleración apuntando hacia afuera en sentido contrario. El vector de la partícula 1 es el doble de largo que el de la partícula 2."></figure><p>Una estudiante nota que, de acuerdo a la figura, la magnitud de aceleración en la partícula 1 es el doble que la de la partícula 2.</p>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F2 Q115 contexto'; end if;
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('45adf8ca-8a45-4f00-ba03-079363e995a1', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un estudiante observa que cuando se coloca un botellón de agua de 20 kg sobre una base sostenida por dos vasos de icopor vacíos, los vasos son aplastados. Sin embargo, si se aumenta el número de vasos para soportar el botellón, los vasos sí lo sostienen, como se muestra en la figura. El estudiante realiza un experimento y obtiene los siguientes resultados.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q97-botellones.webp" loading="lazy" alt="Montajes del botellón sobre vasos de icopor. Con pocos vasos estos se aplastan; al aumentar su número, sostienen el botellón."></figure><div class="ctx-datos" role="region" aria-label="Resultados del experimento" tabindex="0"><table class="ctx-table ctx-table-nativa"><caption>Resultados del experimento</caption><thead><tr><th scope="col">Peso del botellón (N)</th><th scope="col">Número de vasos</th><th scope="col">Presión (Pa)</th></tr></thead><tbody><tr><th scope="row">196</th><td>1</td><td>2,00</td></tr><tr><th scope="row">196</th><td>2</td><td>1,00</td></tr><tr><th scope="row">196</th><td>3</td><td>0,67</td></tr><tr><th scope="row">196</th><td>4</td><td>0,50</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9a731a36-49bf-4e11-a463-e8d689cf422f', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Camilo observa un martillo que se encuentra adherido a un eje de giro, el cual golpea un clavo sobre una superficie de madera, tal y como muestra la figura.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q98-martillo.webp" loading="lazy" alt="Martillo sujeto a un eje: la altura después del primer golpe es mayor que la altura después del segundo golpe."></figure><p>Luego de golpear el clavo, el martillo se sube a una altura menor que la del primer golpe, para luego volver a golpear el clavo. Esto lo hace en repetidas ocasiones, hasta que finalmente se detiene.</p>');
insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'cf5cd08d-5368-4256-ad62-2cd0649eb52a', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'dinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  '45adf8ca-8a45-4f00-ba03-079363e995a1', 'Dinámica y fuerzas',
  'De acuerdo a los resultados obtenidos por el estudiante, ¿por qué un número suficiente de vasos puede llegar a sostener el botellón sin ser aplastados?',
  array['Porque la fuerza de los vasos disminuye, conforme el peso del botellón de agua cambia.', 'Porque al aumentar el número de botellones se mantiene constante el peso de los vasos.', 'Porque al aumentar el número de vasos, disminuye la presión ejercida por el botellón sobre cada vaso.', 'Porque al disminuir la presión del recipiente de agua disminuye el peso del botellón.'],
  'Busca qué cantidad permanece constante y cuál disminuye al aumentar los apoyos.', 'publicada', 'modelo', '96b88140b71b04ab06c9d3aa1d254ab8', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('cf5cd08d-5368-4256-ad62-2cd0649eb52a', 2, 'El peso del botellón permanece en 196 N. Al repartirlo entre más vasos aumenta el área de apoyo total y disminuye la fuerza que soporta cada vaso. La tabla muestra que la presión disminuye al aumentar el número de vasos. No se reduce el peso del botellón: cambia cómo se distribuye sobre el soporte.');
insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '012b121c-a7e7-4ed4-9dd5-30756955f2c4', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'energia-y-trabajo'),
  (select id from public.lotes where codigo = '2026-B'),
  '9a731a36-49bf-4e11-a463-e8d689cf422f', 'Energía y trabajo',
  'Teniendo en cuenta la información anterior, ¿cómo es la variación de la energía mecánica del martillo y del clavo cuando el martillo ha regresado a una altura menor?',
  array['La energía mecánica del martillo ha disminuido y la del clavo ha permanecido constante.', 'La energía mecánica del martillo ha presionado mientras que la del clavo ha disminuido.', 'La energía mecánica del clavo y del martillo han aumentado tras cada golpe.', 'La energía mecánica que posee el martillo y el clavo permanece constante.'],
  'Compara las alturas máximas alcanzadas y distingue la energía mecánica de otras formas de energía.', 'publicada', 'modelo', '26108c292b3900adda8610926a2241d2', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('012b121c-a7e7-4ed4-9dd5-30756955f2c4', 0, 'Al comparar las alturas máximas, el martillo está momentáneamente en reposo y su energía potencial es menor tras cada golpe. Parte de su energía se transfiere a la madera, al clavo y al entorno por deformación, calentamiento y sonido. La respuesta propuesta supone que se compara el clavo en reposo y se desprecia su pequeño cambio de altura. La opción que dice «ha presionado» contiene una errata del PDF; se conserva sin inventar el término faltante. Requiere revisión docente.');
